# ===== HOUDINI WALL DESTRUCTION =====
"""
NODE NETWORK:

1. WALL: Box with UVs
   |
2. VORONOI FRACTURE: Input wall geometry, scatter 50-100 points
   |    Creates fracture pieces based on Voronoi cells
   |
3. EXPLODED VIEW: Separate pieces by random offset
   |
4. ATTRIBUTE WRANGLE:
   |    - Set each piece's unique color (for visualization)
   |    - Assign random strength values
   |    - Calculate piece volume and mass
   |
5. ASSEMBLY: Glue pieces together with constraints (RBD Constraints)
   |    - Glue constraints hold pieces together until broken
   |    - Strength threshold determines how much force to break
   |
6. ACTIVE RIGID BODY: Convert to physics simulation
   |    - Apply gravity
   |    - Set collision shapes (convex hull per piece)
   |
7. ADD IMPACT: Sphere with velocity hits the wall
   |    - Calculate force of impact
   |    - Break glue constraints within impact radius
   |
8. SIMULATE: Run physics simulation (100 frames)
   |
9. EXPORT:
   - Animated geometry (bake simulation to keyframes)
   - Individual pieces for game engine import
   - Destruction event data (timing, forces)
"""

// VEX code for piece properties
// Runs on each primitive in the fractured mesh

// Calculate piece mass based on volume
float volume = primintrinsic(0, "measuredvolume", @primnum);
@mass = volume * chf("density");

// Random strength for each glue constraint
@strength = fit01(rand(@primnum + 123), 0.5, 1.5) * chf("base_strength");

// Set as active rigid body
@active = 1;

// Add some randomness to the fracture for realism
vector centroid = primintrinsic(0, "boundscenter", @primnum);
@P += (rand(@primnum) - 0.5) * 0.1;

# ===== IK RETARGETING IN UNREAL ENGINE =====
"""
UNREAL IK RETARGETING PIPELINE:

1. PREPARE RIGS
   - Source: The skeleton the mocap was recorded on
   - Target: Your character's skeleton
   - Both must have similar bone hierarchy for good results

2. CREATE IK RETARGETER
   - Asset: IK Retargeter (new in UE5)
   - Select source skeleton and target skeleton
   - Chain mapping: which source chain maps to which target chain
     (LeftArm -> LeftArm, RightLeg -> RightLeg, etc.)

3. ADJUST RETARGETING
   - Pole Vector: Controls elbow/knee direction
   - Twist Correction: Fixes forearm/upper leg twist
   - Foot Lock: Prevents foot sliding
   - Ground Adjustment: Handles height differences

4. BAKE TO ANIM SEQUENCE
   - Convert retargeted animation to a new animation asset
   - Or use Retargeter at runtime (for dynamic characters)
"""

// C++ Runtime retargeting with IK
#include "IKRetargeter.h"
#include "IKRetargetProcessor.h"

void AMyCharacter::ApplyMocapToCharacter(UAnimSequence* SourceAnimation)
{
    // Get the IK retarget asset
    UIKRetargeter* Retargeter = LoadObject<UIKRetargeter>(nullptr, TEXT("/Game/Rigs/HumanToOrcRetargeter"));

    if (Retargeter)
    {
        // Create processor
        UIKRetargetProcessor* Processor = Retargeter->CreateProcessor(
            GetMesh()->GetSkeleton(),
            SourceAnimation->GetSkeleton()
        );

        if (Processor)
        {
            // Configure settings
            Processor->SetIKChainSpeedThreshold(10.0f);
            Processor->SetGoalBone(EBasicIKSolverType::FullBodyIK, "ik_foot_root");

            // Process the animation
            Processor->RunRetargeting(SourceAnimation, GetMesh()->GetAnimInstance());
        }
    }
}

// ===== MOTION MATCHING BASICS =====
/*
Motion Matching is the technology behind games like The Last of Us Part 2
and the Assassin's Creed series.

HOW IT WORKS:
1. Database of thousands of animation clips
2. Each frame, calculate which clip best matches:
   - Current character position/velocity
   - Desired input direction/speed
   - Previous animation (for smooth transitions)
3. Blend to the best matching clip
4. Result: Incredibly natural movement with no visible transitions

UNREAL 5: Motion Matching is built in via PoseSearch database.
*/

// Unreal C++: Request animation from PoseSearch
UPoseSearchDatabase* AnimDB = LoadObject<UPoseSearchDatabase>(nullptr, TEXT("/Game/PoseSearch/LocomotionDB"));

void AMyCharacter::UpdateMovementAnimation()
{
    if (AnimDB)
    {
        FSearchResult SearchResult;
        FPoseSearchQuery Query;

        // Set query parameters
        Query.SetDesiredSpeed(GetVelocity().Length());
        Query.SetDesiredDirection(GetLastMovementInputVector());
        Query.SetCurrentAnimAsset(GetCurrentAnimSequence());
        Query.SetCurrentAnimTime(GetAnimInstance()->GetCurrentTime());

        // Search database for best match
        if (AnimDB->Search(Query, SearchResult))
        {
            // Blend to matched animation
            PlayAnim(SearchResult.AnimAsset, SearchResult.BlendTime);
        }
    }
}
